async (cursor, num, params) => {
  if (location.hostname !== 'www.photopea.com') throw new Error('[photopea-mask] 这张标签没连上 photopea.com（现在是 ' + location.href.slice(0, 60) + '，多半是连接被掐断）：去那张标签按一次刷新，别关它');
  if (window._cf_chl_opt || /请稍候|Just a moment|安全验证/.test(document.title + ' ' + (document.body ? document.body.innerText.slice(0, 200) : ''))) throw new Error('[photopea-mask] Photopea 标签停在 Cloudflare 真人验证页：去那张「Photopea API」标签点一下验证（只需一次，标签常驻不关），再跑');
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const pageStart = Date.now();
  const images = String(params.images || '').split('\n').filter(Boolean);
  if (images.some(u => !u.startsWith('data:image/'))) throw new Error('[photopea-mask] images 要是 data:image/... 的 data URL（按换行拼）');
  // 本地文件那一路：上一步 setFiles 已把文件放进宿主页的 <input id=stream-files>，这里只收 File 对象。读完就清空——input 不清，下一轮没给 files 时会把上一轮的再装一遍。
  const inp = document.getElementById('stream-files'); const files = inp ? [...(inp.files || [])] : []; if (inp) inp.value = '';
  if (!files.length && !images.length) throw new Error('[photopea-mask] files（本地路径）和 images（data URL）至少给一样');
  // —— 按 masks 生成 Photopea 脚本（选区 → 蒙版 / 擦除），一层一段；层用装入后的名字 img<i> 找 ——
  let masks; try { masks = JSON.parse(params.masks); } catch (e) { throw new Error('[photopea-mask] masks 不是合法 JSON: ' + e.message); }
  if (!Array.isArray(masks) || !masks.length) throw new Error('[photopea-mask] masks 要是非空数组');
  // 切法只有"擦"：选区反选后 clear。图层蒙版建不了——Mk/Msk 描述符四种写法（RvlS / HdSl / 无 Usng / stringID make）
  // 全部让脚本静默死（2026-09-24 活体）。擦是破坏性的，但选区抗锯齿 + feather 这两样有；要能手拖的缝，导 PSD 后在
  // Photopea 里把这一层的透明度转成蒙版（人一步）。
  // 魔棒 = setd（同 photopea-cutout）：从种子按容差连通生长，抗锯齿边；采样当前层。
  const wand = (x, y, tol, cont) => 'var c = charIDToTypeID; var desc = new ActionDescriptor(); var ref = new ActionReference(); ref.putProperty(c("Chnl"), c("fsel")); desc.putReference(c("null"), ref); var pt = new ActionDescriptor(); pt.putUnitDouble(c("Hrzn"), c("#Pxl"), ' + x + '); pt.putUnitDouble(c("Vrtc"), c("#Pxl"), ' + y + '); desc.putObject(c("T   "), c("Pnt "), pt); desc.putInteger(c("Tlrn"), ' + tol + '); desc.putBoolean(c("AntA"), true); desc.putBoolean(c("Cntg"), ' + cont + '); executeAction(c("setd"), desc, DialogModes.NO);';
  const nv = (v, d) => (v === undefined || v === null || v === '' ? d : Number(v));
  // 先把所有 img<i> 的引用抓在手里再动手：一项改了名，后面同一层的项（补丁层常见）就按名找不到了。
  const nLayers = files.length + images.length;
  let script = 'var d = app.activeDocument; var LS = [];';
  for (let i = 0; i < nLayers; i++) script += ' LS[' + i + '] = d.layers.getByName("img' + i + '");';
  masks.forEach((mk, k) => {
    const i = Number(mk.layer);
    if (!Number.isInteger(i) || i < 0 || i >= nLayers) throw new Error('[photopea-mask] masks[' + k + '].layer 要是装入序号 0..' + (nLayers - 1));
    script += ' var L = LS[' + i + '];';
    if (mk.duplicate) script += ' L = L.duplicate();';                      // 补丁层：动副本，原层不碰
    script += ' d.activeLayer = L;';
    if (mk.name) script += ' L.name = ' + JSON.stringify(String(mk.name)) + ';';
    if (mk.hidden) script += ' L.opacity = 0;';                                // 参考层：PSD 里留着但不显示，PNG 导出自然不含它。**别改回 L.visible = false**：2026-09-28 实测 Photopea 脚本里给任何一层设 visible（true/false 都一样）或执行 Hd/Shw 动作，效果都是「独显」开关（等同 Alt 点眼睛）——第一次只剩它自己显示、其余全关，第二次全部恢复，没法单独关一层；导出的 PSD 打开就是只剩这层参考层可见。退而用不透明度 0：看不见、不进合成，要看时把不透明度拉上来
    if (mk.opacity !== undefined && mk.opacity !== null && mk.opacity !== '') script += ' L.opacity = ' + nv(mk.opacity, 100) + ';';
    if (Array.isArray(mk.offset)) script += ' L.translate(' + nv(mk.offset[0], 0) + ', ' + nv(mk.offset[1], 0) + ');';   // 先挪再蒙：让旁边干净的材质落到坏点上
    const polys = Array.isArray(mk.polygons) ? mk.polygons : (Array.isArray(mk.polygon) ? [mk.polygon] : []);
    const within = Array.isArray(mk.within) ? mk.within : null;
    if (within && within.length < 3) throw new Error('[photopea-mask] masks[' + k + '].within 要是至少 3 个点的多边形');
    if (polys.length || mk.wand || within) {
      script += ' d.selection.deselect();';
      if (!polys.length && !mk.wand) script += ' d.selection.selectAll();';   // 只给 within:整层先全选,再被 within 裁
      if (mk.wand) { const s = mk.wand.seed || []; script += ' ' + wand(nv(s[0], 0), nv(s[1], 0), nv(mk.wand.tolerance, 24), mk.wand.contiguous === false ? 'false' : 'true'); }
      polys.forEach((poly, j) => { if (!Array.isArray(poly) || poly.length < 3) throw new Error('[photopea-mask] masks[' + k + '] 的多边形至少 3 个点'); script += ' d.selection.select(' + JSON.stringify(poly) + ((j || mk.wand) ? ', SelectionType.EXTEND' : '') + ');'; });
      const subs = Array.isArray(mk.subtract) ? mk.subtract : [];
      subs.forEach((poly, j) => { if (!Array.isArray(poly) || poly.length < 3) throw new Error('[photopea-mask] masks[' + k + '].subtract 的多边形至少 3 个点'); script += ' d.selection.select(' + JSON.stringify(poly) + ', SelectionType.DIMINISH);'; });
      if (mk.invert) script += ' d.selection.invert();';
      if (within) script += ' d.selection.select(' + JSON.stringify(within) + ', SelectionType.INTERSECT);';   // within:最后再和这块求交——层只留在它的领地里(图层组的区域)
      const ct = nv(mk.contract, 0); if (ct > 0) script += ' d.selection.contract(' + ct + ');'; else if (ct < 0) script += ' d.selection.expand(' + (-ct) + ');';
      const fe = nv(mk.feather, 0); if (fe > 0) script += ' d.selection.feather(' + fe + ');';
      script += ' d.selection.invert(); d.selection.clear();';
      script += ' d.selection.deselect();';
    }
    // erase：保留切完再擦几块。每块 = 魔棒（种子+容差，连通）→ expand 扩边 → within 多边形求交（只动框里）→ feather → 清掉。
    // 用途：旧抠图里没抠掉的白底（龙头拱里那种封闭的口袋），和低清抠图放大后的锯齿边（种子点在外面透明区，扩几 px 把串珠削掉）。
    (Array.isArray(mk.erase) ? mk.erase : []).forEach((er, j) => {
      const s = (er && er.seed) || []; if (s.length !== 2) throw new Error('[photopea-mask] masks[' + k + '].erase[' + j + '].seed 要是 [x, y]');
      script += ' d.selection.deselect(); ' + wand(nv(s[0], 0), nv(s[1], 0), nv(er.tolerance, 24), er.contiguous === false ? 'false' : 'true');
      const ex = nv(er.expand, 0); if (ex > 0) script += ' d.selection.expand(' + ex + ');';
      if (er.within !== undefined) { if (!Array.isArray(er.within) || er.within.length < 3) throw new Error('[photopea-mask] masks[' + k + '].erase[' + j + '].within 至少 3 个点'); script += ' d.selection.select(' + JSON.stringify(er.within) + ', SelectionType.INTERSECT);'; }
      const ef = nv(er.feather, 0); if (ef > 0) script += ' d.selection.feather(' + ef + ');';
      script += ' d.selection.clear(); d.selection.deselect();';
    });
    script += ' app.echoToOE("mask#' + k + ' ok " + L.name);';
  });
  // group:出 PSD 时按路径编组("柜台/主岛台/灶列",斜杠分层级)。Photopea 脚本里把层「移进」已有的组不行(move INSIDE 会复制一份、duplicate 进组会把层丢掉,2026-09-29 实测),
  // 能用的是 Ctrl+G 那条动作:按名选中几层(slct + addToSelection)→ make layerSection。所以从最深的组往上,一组一次把直接成员(层 + 已建好的子组)选中编组。
  // 同组的层在栈里必须挨着(编组会把成员收拢到最上面那个成员的位置,不挨着就改了叠放顺序);层名、组名全文档唯一。PNG 导出不编组(不影响像素)。
  if (String(params.format || 'png') === 'psd' && masks.some(m => m.group)) {
    const kids = {}, paths = new Set(), seen = new Set(masks.map(m => String(m.name || '')));
    masks.forEach((m, k) => { if (!m.group) return; if (!m.name) throw new Error('[photopea-mask] masks[' + k + '] 给了 group 就要给 name'); const parts = String(m.group).split('/').filter(Boolean); for (let i = 1; i <= parts.length; i++) paths.add(parts.slice(0, i).join('/')); const p = parts.join('/'); (kids[p] = kids[p] || []).push(String(m.name)); });
    [...paths].forEach(p => { const leaf = p.split('/').pop(); if (seen.has(leaf)) throw new Error('[photopea-mask] 组名「' + leaf + '」和别的层 / 组重名'); seen.add(leaf); const i = p.lastIndexOf('/'); if (i > 0) { const q = p.slice(0, i); (kids[q] = kids[q] || []).push(leaf); } });
    script += ' function PMsel(n, add) { var c = charIDToTypeID, s = stringIDToTypeID; var ds = new ActionDescriptor(); var r = new ActionReference(); r.putName(c("Lyr "), n); ds.putReference(c("null"), r); if (add) ds.putEnumerated(s("selectionModifier"), s("selectionModifierType"), s("addToSelection")); ds.putBoolean(c("MkVs"), false); executeAction(c("slct"), ds, DialogModes.NO); }';
    script += ' function PMgroup(n) { var c = charIDToTypeID, s = stringIDToTypeID; var ds = new ActionDescriptor(); var r = new ActionReference(); r.putClass(s("layerSection")); ds.putReference(c("null"), r); var r2 = new ActionReference(); r2.putEnumerated(c("Lyr "), c("Ordn"), c("Trgt")); ds.putReference(c("From"), r2); executeAction(c("Mk  "), ds, DialogModes.NO); d.activeLayer.name = n; }';
    [...paths].sort((a, b) => b.split('/').length - a.split('/').length).forEach(p => {
      const ms = kids[p] || []; if (!ms.length) return;
      ms.forEach((n, j) => { script += ' PMsel(' + JSON.stringify(n) + ', ' + (j ? 'true' : 'false') + ');'; });
      script += ' PMgroup(' + JSON.stringify(p.split('/').pop()) + '); app.echoToOE(' + JSON.stringify('group ok ' + p) + ');';
    });
  }
  const format = String(params.format || 'png');
  const W = params.width ? Number(params.width) : 0, H = params.height ? Number(params.height) : 0;
  if ((W || H) && !(W > 0 && H > 0)) throw new Error('[photopea-mask] width/height 要一起给、都是正整数');
  const scriptMs = Math.min(Math.max(Number(params.timeoutMs || 20000), 1000), 25000);
  // —— Photopea 宿主：同源 iframe（photopea.com 顶层不听 postMessage，嵌成 iframe 才听）——
  const ensureFrame = async () => {
    let f = document.getElementById('pp');
    if (f) { // 上一轮留下的热 iframe：应一声就复用，不应就换新的
      const alive = await new Promise(res => { const h = e => { if (e.source === f.contentWindow && e.data === 'pong') { window.removeEventListener('message', h); res(true); } }; window.addEventListener('message', h); setTimeout(() => { window.removeEventListener('message', h); res(false); }, 4000); f.contentWindow.postMessage('app.echoToOE("pong");', '*'); });
      if (alive) return f;
      f.remove();
    }
    f = document.createElement('iframe'); f.id = 'pp'; f.style.cssText = 'position:fixed;left:0;top:0;width:100vw;height:100vh;border:0;background:#fff;z-index:2147483647';
    const ready = new Promise((res, rej) => { const h = e => { if (e.source === f.contentWindow && e.data === 'done') { window.removeEventListener('message', h); res(); } }; window.addEventListener('message', h); setTimeout(() => { window.removeEventListener('message', h); rej(new Error('[photopea-mask] Photopea iframe 25s 没就绪')); }, 25000); });
    f.src = 'https://www.photopea.com/#' + encodeURIComponent(JSON.stringify({ environment: {} }));
    document.body.appendChild(f);
    await ready;
    return f;
  };
  const f = await ensureFrame();
  // 跑一段 Photopea 脚本，等它最后一句 echo 的标记；二进制（saveToOE）顺手收下。
  // Photopea 脚本抛错时**不报错也不发 done**，所以：用户脚本包一层 try/catch 把 e 回显成 "ERR:…"（能抓到的那类），
  // 抓不到的（引擎内部死掉）靠超时，把已收到的回音和脚本前 200 字一起抛出来。
  const pp = (script, ms, label) => new Promise((res, rej) => {
    const mark = 'ok#' + Math.random().toString(36).slice(2, 8); let bin = null; const got = [];
    const h = e => { if (e.source !== f.contentWindow) return; if (e.data instanceof ArrayBuffer) { bin = e.data; return; } if (typeof e.data !== 'string') return; got.push(e.data); if (e.data === mark) { window.removeEventListener('message', h); clearTimeout(t); res({ bin, got }); } };
    const t = setTimeout(() => { window.removeEventListener('message', h); rej(new Error('[photopea-mask] ' + label + ' ' + ms + 'ms 内没跑完（Photopea 脚本出错时不报错、只是没有回音；常见死因见 README 的可用表）。脚本开头: ' + script.slice(0, 200).replace(/\s+/g, ' ') + ' | 收到的回音: ' + (got.join(' / ') || '（无）'))); }, ms);
    window.addEventListener('message', h);
    f.contentWindow.postMessage(script + '\napp.echoToOE(' + JSON.stringify(mark) + ');', '*');
  });
  let B = 0; // 清完临时文档后已有的文档数（用户自己开着的）；本轮的文档从 app.documents[B] 起
  const probe = async () => (await pp('app.echoToOE("docs=" + app.documents.length);', 5000, '探文档数')).got.find(s => s.startsWith('docs='));
  const waitDocs = async (n, ms) => { const t0 = Date.now(); for (;;) { const s = await probe(); if (s === 'docs=' + (B + n)) return; if (Date.now() - t0 > ms) throw new Error('[photopea-mask] 等文档就绪超时，现在 ' + s + '，要 docs=' + n); await sleep(300); } };
  // —— 装入：先清场；有画幅就先建透明画布再把每张图开成文档、duplicate 成画布的一层（img0 在最底）；没画幅就按顺序各开成文档（app.documents[i] = 第 i 张）——
  await pp('for (var i = app.documents.length - 1; i >= 0; i--) if (String(app.documents[i].name).indexOf("~stream~") === 0) app.documents[i].close();', 8000, '清掉上轮残留的临时文档');
  B = Number(((await probe()) || 'docs=0').slice(5).split(' ')[0]) || 0;
  await waitDocs(0, 8000);
  if (W) {
    await pp('app.documents.add(' + W + ', ' + H + ', 72, "~stream~canvas", NewDocumentMode.RGB, DocumentFill.TRANSPARENT);', 8000, '新建画布');
    await waitDocs(1, 8000);
  }
  // 装入顺序：先本地文件、后 data URL，序号连着排（img<i>）。ArrayBuffer 直接 postMessage 给 iframe 就开成一个文档
  // （Photopea 的消息 API：字符串当脚本、二进制当文件，实测 2026-09-24），不经 base64、不占脚本预算。
  const openBinary = (buf, label) => new Promise((res, rej) => { const h = e => { if (e.source === f.contentWindow && e.data === 'done') { window.removeEventListener('message', h); clearTimeout(t); res(); } }; const t = setTimeout(() => { window.removeEventListener('message', h); rej(new Error('[photopea-mask] ' + label + ' 20s 没开成文档')); }, 20000); window.addEventListener('message', h); f.contentWindow.postMessage(buf, '*'); });
  const total = files.length + images.length;
  for (let i = 0; i < total; i++) {
    if (i < files.length) await openBinary(await files[i].arrayBuffer(), '打开第 ' + i + ' 个文件 ' + files[i].name);
    else await pp('app.open(' + JSON.stringify(images[i - files.length]) + ');', 20000, '打开第 ' + i + ' 张图');
    await waitDocs(W ? 2 : i + 1, 20000);
    if (W) {
      await pp('var src = app.activeDocument; src.layers[0].duplicate(app.documents[' + B + '], ElementPlacement.PLACEATBEGINNING); src.close(); app.activeDocument = app.documents[' + B + ']; app.activeDocument.layers[0].name = "img' + i + '";', 8000, '把第 ' + i + ' 张图放进画布');
      await waitDocs(1, 8000);
    } else {
      await pp('app.activeDocument.layers[0].name = "img' + i + '"; app.activeDocument.name = "~stream~img' + i + '";', 5000, '给第 ' + i + ' 张图命名');
    }
    if (Date.now() - pageStart > 22000) throw new Error('[photopea-mask] 图太多，装入就用掉了一次求值的 30s 预算（已装 ' + (i + 1) + ' 张）');
  }
  if (!W) await pp('app.activeDocument = app.documents[' + B + '];', 5000, '切回第 0 张图');
  // —— 用户脚本原样执行（外面包一层 try/catch 抓能抓的错）——
  const budget = Math.min(scriptMs, 26000 - (Date.now() - pageStart));
  const r = await pp('var BASE = ' + B + ';\ntry {\n' + script + '\n} catch (e) { app.echoToOE("ERR:" + (e && e.message ? e.message : e)); }', budget, '用户脚本');
  const err = r.got.find(s => s.startsWith('ERR:'));
  if (err) throw new Error('[photopea-mask] 脚本抛错: ' + err.slice(4));
  const echoes = r.got.filter(s => !s.startsWith('ok#') && s !== 'done');
  // —— 导出脚本结束时的 activeDocument ——
  const { bin, got } = await pp('var d = app.activeDocument; app.echoToOE("size=" + d.width + "x" + d.height); app.echoToOE("layers=" + d.layers.length); app.echoToOE("doc=" + d.name); d.saveToOE(' + JSON.stringify(format) + ');', 20000, '导出');
  if (!bin) throw new Error('[photopea-mask] saveToOE(' + format + ') 没回二进制: ' + got.join(' / '));

  const keepName = String(params.keep || '');
  if (keepName) await pp('app.activeDocument.name = ' + JSON.stringify(keepName) + '; var kd = app.activeDocument; ' + 'for (var i = app.documents.length - 1; i >= 0; i--) if (String(app.documents[i].name).indexOf("~stream~") === 0) app.documents[i].close();' + ' app.activeDocument = kd;', 8000, '留下结果');
  else await pp('for (var i = app.documents.length - 1; i >= 0; i--) if (String(app.documents[i].name).indexOf("~stream~") === 0) app.documents[i].close();', 8000, '收尾');
  const u8 = new Uint8Array(bin); let s = ''; for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000));
  const pick = k => (got.find(x => x.startsWith(k + '=')) || '').slice(k.length + 1);
  return { items: [{ guid: 'run-' + Date.now(), format, size: pick('size'), layers: pick('layers'), doc: pick('doc'), echoes: echoes.join('\n'), bytes: String(u8.length), data: btoa(s) }], cursor: '' };
}
